import { CircuitModel } from './types';

export function exportToQiskit(circuit: CircuitModel): string {
  const { qubitsCount, classicalBitsCount, gates } = circuit;
  const sortedGates = [...gates].sort((a, b) => a.col - b.col);

  const lines: string[] = [
    '# Generated by QuantumGate Cloud Lab',
    '# Compatible with Qiskit 1.0+ and Qiskit Aer',
    '',
    'from qiskit import QuantumCircuit, transpile',
    'from qiskit_aer import AerSimulator',
    'from qiskit.visualization import plot_histogram',
    'import numpy as np',
    '',
    `# Create a Quantum Circuit with ${qubitsCount} qubits and ${classicalBitsCount} classical bits`,
    `qc = QuantumCircuit(${qubitsCount}, ${classicalBitsCount})`,
    '',
  ];

  for (const g of sortedGates) {
    const p = g.params;
    switch (g.type) {
      case 'I':
        lines.push(`qc.id(${g.target})`);
        break;
      case 'X':
        lines.push(`qc.x(${g.target})`);
        break;
      case 'Y':
        lines.push(`qc.y(${g.target})`);
        break;
      case 'Z':
        lines.push(`qc.z(${g.target})`);
        break;
      case 'H':
        lines.push(`qc.h(${g.target})`);
        break;
      case 'S':
        lines.push(`qc.s(${g.target})`);
        break;
      case 'Sdg':
        lines.push(`qc.sdg(${g.target})`);
        break;
      case 'T':
        lines.push(`qc.t(${g.target})`);
        break;
      case 'Tdg':
        lines.push(`qc.tdg(${g.target})`);
        break;
      case 'SX':
        lines.push(`qc.sx(${g.target})`);
        break;
      case 'RX':
        lines.push(`qc.rx(${p?.theta ?? 0}, ${g.target})`);
        break;
      case 'RY':
        lines.push(`qc.ry(${p?.theta ?? 0}, ${g.target})`);
        break;
      case 'RZ':
        lines.push(`qc.rz(${p?.theta ?? 0}, ${g.target})`);
        break;
      case 'U3':
        lines.push(`qc.u(${p?.theta ?? 0}, ${p?.phi ?? 0}, ${p?.lambda ?? 0}, ${g.target})`);
        break;
      case 'CX':
        lines.push(`qc.cx(${g.control ?? 0}, ${g.target})`);
        break;
      case 'CZ':
        lines.push(`qc.cz(${g.control ?? 0}, ${g.target})`);
        break;
      case 'CP':
        lines.push(`qc.cp(${p?.theta ?? Math.PI}, ${g.control ?? 0}, ${g.target})`);
        break;
      case 'CRX':
        lines.push(`qc.crx(${p?.theta ?? Math.PI}, ${g.control ?? 0}, ${g.target})`);
        break;
      case 'SWAP':
        lines.push(`qc.swap(${g.target}, ${g.target2 ?? ((g.target + 1) % qubitsCount)})`);
        break;
      case 'CCX':
        lines.push(`qc.ccx(${g.control ?? 0}, ${g.control2 ?? 1}, ${g.target})`);
        break;
      case 'CSWAP':
        lines.push(`qc.cswap(${g.control ?? 0}, ${g.target}, ${g.target2 ?? ((g.target + 1) % qubitsCount)})`);
        break;
      case 'MEASURE':
        lines.push(`qc.measure(${g.target}, ${g.classicalBit ?? g.target})`);
        break;
    }
  }

  lines.push('');
  lines.push('# Draw ASCII Circuit Diagram');
  lines.push('print("Circuit Diagram:")');
  lines.push('print(qc.draw(output="text"))');
  lines.push('');
  lines.push('# Execute on Aer Statevector Simulator');
  lines.push('simulator = AerSimulator()');
  lines.push('compiled_circuit = transpile(qc, simulator)');
  lines.push('job = simulator.run(compiled_circuit, shots=1024)');
  lines.push('result = job.result()');
  lines.push('counts = result.get_counts(compiled_circuit)');
  lines.push('print("Measurement Counts (1024 shots):", counts)');

  return lines.join('\n');
}
